import React, { useState, useEffect } from "react";
import "./CrosswordGame.css";

const CrosswordGame = ({
  question,
  onAnswerSubmit,
  timer,
  answerSubmitted,
  showFeedback,
  isCorrectAnswer,
  onAnswerChange,
}) => {
  const [foundWords, setFoundWords] = useState([]);
  const [attempts, setAttempts] = useState(0);
  const [selectedCells, setSelectedCells] = useState([]);
  const [currentDirection, setCurrentDirection] = useState("across");
  const [gameStartTime] = useState(Date.now());

  // Initialize game state when question changes
  useEffect(() => {
    if (question) {
      setFoundWords([]);
      setAttempts(0);
      setSelectedCells([]);
      setCurrentDirection("across");
    }
  }, [question]);

  // Handle game completion when all words are found
  useEffect(() => {
    if (question && foundWords.length === question.words.length && !answerSubmitted) {
      const timeTaken = Math.floor((Date.now() - gameStartTime) / 1000);
      const scoreData = {
        foundWords: foundWords.length,
        totalWords: question.words.length,
        attempts: attempts,
        timeTaken: timeTaken,
      };
      onAnswerSubmit(scoreData);
    }
  }, [foundWords, question, attempts, answerSubmitted, gameStartTime, onAnswerSubmit]);

  const isCellSelected = (row, col) => {
    return selectedCells.some(cell => cell.row === row && cell.col === col);
  };

  const isWordFound = (word) => {
    return foundWords.includes(word);
  };

  const getCellClass = (row, col) => {
    let className = "crossword-cell";
    
    if (question.grid[row][col] === "#") {
      className += " blocked";
    } else {
      className += " empty";
      
      // Check if this cell is part of any word
      question.words.forEach(wordObj => {
        const { word, start, direction } = wordObj;
        
        if (direction === "across" && start.row === row) {
          for (let i = 0; i < word.length; i++) {
            if (start.col + i === col) {
              if (isWordFound(word)) {
                className += " found";
              } else if (isCellSelected(row, col)) {
                className += " selected";
              }
              return;
            }
          }
        } else if (direction === "down" && start.col === col) {
          for (let i = 0; i < word.length; i++) {
            if (start.row + i === row) {
              if (isWordFound(word)) {
                className += " found";
              } else if (isCellSelected(row, col)) {
                className += " selected";
              }
              return;
            }
          }
        }
      });
    }
    
    return className;
  };

  const handleCellClick = (row, col) => {
    if (answerSubmitted || question.grid[row][col] === "#") return;

    // Prevent selecting cells that are part of already found words
    const isPartOfFoundWord = question.words.some(wordObj => {
      if (isWordFound(wordObj.word)) {
        const { start, direction, word } = wordObj;
        if (direction === "across" && start.row === row) {
          return col >= start.col && col < start.col + word.length;
        } else if (direction === "down" && start.col === col) {
          return row >= start.row && row < start.row + word.length;
        }
      }
      return false;
    });

    if (isPartOfFoundWord) {
      // Simply return without doing anything - no error, just ignore the click
      return;
    }

    // Toggle selection or select new cells
    const newSelectedCells = [...selectedCells];
    const cellIndex = newSelectedCells.findIndex(
      cell => cell.row === row && cell.col === col
    );

    if (cellIndex > -1) {
      newSelectedCells.splice(cellIndex, 1);
    } else {
      newSelectedCells.push({ row, col });
    }

    setSelectedCells(newSelectedCells);
    setAttempts(prev => prev + 1);
  };

  const checkSelectedWord = () => {
    if (selectedCells.length === 0) return;

    // Sort selected cells
    const sortedCells = [...selectedCells].sort((a, b) => {
      if (a.row === b.row) return a.col - b.col;
      return a.row - b.row;
    });

    // Determine direction
    let direction = "across";
    if (sortedCells.length > 1) {
      if (sortedCells[0].row === sortedCells[1].row) {
        direction = "across";
      } else if (sortedCells[0].col === sortedCells[1].col) {
        direction = "down";
      }
    }

    // Extract word from grid
    let word = "";
    sortedCells.forEach(cell => {
      word += question.grid[cell.row][cell.col];
    });

    // Check if word matches any in the list
    const matchedWord = question.words.find(wordObj => 
      wordObj.word === word && 
      wordObj.direction === direction
    );

    if (matchedWord && !isWordFound(matchedWord.word)) {
      setFoundWords(prev => [...prev, matchedWord.word]);
      setSelectedCells([]);
    } else {
      // Word not found - show visual feedback but don't prevent future selections
      setSelectedCells([]);
      // You can add a subtle animation here if needed
    }
  };

  // Auto-check word when selection changes
  useEffect(() => {
    if (selectedCells.length > 0) {
      const timer = setTimeout(() => {
        checkSelectedWord();
      }, 500);
      return () => clearTimeout(timer);
    }
  }, [selectedCells]);

  const handleGiveUp = () => {
    const timeTaken = Math.floor((Date.now() - gameStartTime) / 1000);
    const scoreData = {
      foundWords: foundWords.length,
      totalWords: question.words.length,
      attempts: attempts,
      timeTaken: timeTaken,
    };
    onAnswerSubmit(scoreData);
  };

  if (!question) return null;

  return (
    <div className="crossword-game">
      <h2>Crossword Puzzle</h2>
      
      <div className="crossword-container">
        <div className="crossword-grid">
          {question.grid.map((row, rowIndex) => (
            <div key={rowIndex} className="crossword-row">
              {row.map((cell, colIndex) => (
                <div
                  key={colIndex}
                  className={getCellClass(rowIndex, colIndex)}
                  onClick={() => handleCellClick(rowIndex, colIndex)}
                >
                  {cell !== "#" && cell}
                </div>
              ))}
            </div>
          ))}
        </div>
      </div>

      <div className="crossword-info">
        <div className="words-list">
          <h3>Words to Find:</h3>
          <div className="words-container">
            {question.words.map((wordObj, index) => (
              <div
                key={index}
                className={`word-item ${
                  isWordFound(wordObj.word) ? "found" : "not-found"
                }`}
              >
                {wordObj.word} {wordObj.clue && `- ${wordObj.clue}`}
              </div>
            ))}
          </div>
        </div>
        
        <div className="game-stats">
          <p>Found: {foundWords.length}/{question.words.length}</p>
          <p>Attempts: {attempts}</p>
          <p>Time: {Math.floor((Date.now() - gameStartTime) / 1000)}s</p>
        </div>
      </div>

      {!answerSubmitted && (
        <div className="crossword-controls">
          <button className="give-up-btn" onClick={handleGiveUp}>
            Give Up
          </button>
        </div>
      )}
    </div>
  );
};

export default CrosswordGame;
